export function createWorldAudio(){
 let context=null,buffers=null,phase=null,lastFoot=0;const active=new Set();
 async function unlock(){try{context??=new (window.AudioContext||window.webkitAudioContext)();await context.resume();buffers??=Promise.all(['gunshot.mp3','step-left.wav','step-right.wav'].map(async name=>context.decodeAudioData(await(await fetch(new URL('./audio/'+name,import.meta.url))).arrayBuffer())));await buffers;}catch{buffers=null;}}
 addEventListener('pointerdown',unlock,{passive:true});addEventListener('keydown',unlock,{passive:true});
 async function play(index,volume=1){if(!context||context.state!=='running'||!buffers||volume<=0)return;try{const samples=await buffers;if(active.size>=12){const oldest=active.values().next().value;oldest.stop();active.delete(oldest);}const source=context.createBufferSource(),gain=context.createGain();source.buffer=samples[index];gain.gain.value=volume*(index===0?.5:.35);source.connect(gain).connect(context.destination);active.add(source);source.onended=()=>{active.delete(source);source.disconnect();gain.disconnect();};source.start();}catch{}}
 return {shot(position,state){const distance=position&&state.player?Math.hypot(position.x-state.player.position.x,position.y-state.player.position.y,position.z-state.player.position.z):0;play(0,Math.max(0,1-distance/90));},update(state){const a=state.avatar?.animation;if(!a||!state.inStudio||state.paused||state.seated||state.ragdoll||!a.grounded||a.speed<.3){phase=null;return;}const half=Math.floor(((a.phase+Math.PI/2)%(Math.PI*2))/Math.PI);if(phase!==null&&phase!==half&&state.now-lastFoot>130){play(half+1);lastFoot=state.now;}phase=half;}};
}
